import { MakeLogicType, actions, connect, kea, path, reducers } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { urls } from 'scenes/urls'

import { dataCatalogAgentSyncLogic } from './dataCatalogAgentSyncLogic'

export type DataCatalogTab = 'metrics' | 'relationships' | 'certifications' | 'usage'

export const DATA_CATALOG_TABS: DataCatalogTab[] = ['metrics', 'relationships', 'certifications', 'usage']

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dataCatalogSceneLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    activeTab: DataCatalogTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface dataCatalogSceneLogicActions {
    setActiveTab: (activeTab: DataCatalogTab) => {
        activeTab: DataCatalogTab
    }
}

export type dataCatalogSceneLogicType = MakeLogicType<dataCatalogSceneLogicValues, dataCatalogSceneLogicActions>

export const dataCatalogSceneLogic = kea<dataCatalogSceneLogicType>([
    path(['products', 'data_catalog', 'frontend', 'dataCatalogSceneLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags']],
        logic: [dataCatalogAgentSyncLogic],
    })),
    actions({
        setActiveTab: (activeTab: DataCatalogTab) => ({ activeTab }),
    }),
    reducers({
        activeTab: [
            'metrics' as DataCatalogTab,
            {
                setActiveTab: (_, { activeTab }) => activeTab,
            },
        ],
    }),
    actionToUrl(({ values }) => ({
        setActiveTab: () => {
            if ((router.values.searchParams.tab ?? 'metrics') !== values.activeTab) {
                return urls.dataCatalog(values.activeTab === 'metrics' ? undefined : values.activeTab)
            }
        },
    })),
    urlToAction(({ actions, values }) => ({
        [urls.dataCatalog()]: (_, searchParams) => {
            const allowed =
                DATA_CATALOG_TABS.includes(searchParams.tab) &&
                (searchParams.tab !== 'usage' || !!values.featureFlags[FEATURE_FLAGS.DATA_CATALOG_USAGE])
            const tab = allowed ? searchParams.tab : 'metrics'
            if (tab !== values.activeTab) {
                actions.setActiveTab(tab)
            }
        },
    })),
])
